// /admin — generated by `pnpm gen:screen admin`. First section: gate templates (D-32, Vlad 14 Nov). A director or
// sponsor sets the gates of a scope — every project (base), one client, or a client in one country — adds,
// removes and reorders them, saves or archives. Saving replaces the scope's active template; the API refuses
// other roles. Every string is an i18n key (ocs-ui-screen).
import { useEffect, useState } from 'react';
import { AgentResourceSetup } from './agent-resource.tsx';
import { Button, Card, Form, FormMessage, PageHeader, SelectField, TextField, useI18n } from '@ocs/ui';
import {
  archiveGateTemplateOf,
  loadGateTemplates,
  loadPortfolio,
  saveGateTemplateOf,
  type ClientSummary,
  type GateTemplate,
} from '../api.ts';

interface GateRow {
  key: string;
  name: string;
  readinessDays: string;
}
type Outcome = 'ok' | 'forbidden' | 'invalid' | 'failed';

const BASE = '';
const emptyGate = (): GateRow => ({ key: '', name: '', readinessDays: '' });
/** A key from the gate's name; names in 中文 give none, so the key stays editable. */
const keyOf = (name: string) =>
  name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^[^a-z]+|_+$/g, '')
    .slice(0, 40);

export function AdminPage() {
  const { t } = useI18n();
  const [templates, setTemplates] = useState<GateTemplate[] | 'forbidden' | 'failed' | null>(null);
  const [clients, setClients] = useState<ClientSummary[]>([]);
  const [version, setVersion] = useState(0);
  const [clientId, setClientId] = useState(BASE);
  const [country, setCountry] = useState('');
  const [name, setName] = useState('');
  const [gates, setGates] = useState<GateRow[]>([emptyGate()]);
  const [outcome, setOutcome] = useState<Outcome | null>(null);

  useEffect(() => {
    loadGateTemplates().then(
      (d) => {
        setTemplates(d ?? 'forbidden');
      },
      () => {
        setTemplates('failed');
      },
    );
  }, [version]);
  useEffect(() => {
    loadPortfolio().then(
      (p) => {
        setClients(p.clients);
      },
      () => {
        setClients([]);
      },
    );
  }, []);

  const clientCode = (id: string | null) =>
    id === null ? t('admin.gates.base') : (clients.find((c) => c.id === id)?.shortCode ?? id);
  const scopeOf = (tpl: GateTemplate) =>
    [clientCode(tpl.clientId), tpl.countryCode].filter((x) => x !== null).join(' · ');

  const edit = (tpl: GateTemplate) => {
    setClientId(tpl.clientId ?? BASE);
    setCountry(tpl.countryCode ?? '');
    setName(tpl.name);
    setGates(
      tpl.gates.map((g) => ({
        key: g.key,
        name: g.name,
        readinessDays: g.readinessDays === undefined ? '' : String(g.readinessDays),
      })),
    );
    setOutcome(null);
  };
  const setGate = (n: number, patch: Partial<GateRow>) => {
    setGates((gs) => gs.map((g, i) => (i === n ? { ...g, ...patch } : g)));
  };
  const move = (n: number, by: -1 | 1) => {
    setGates((gs) => {
      const to = n + by;
      if (to < 0 || to >= gs.length) return gs;
      return gs.map((g, i) => (i === n ? gs[to] : i === to ? gs[n] : g) ?? g);
    });
  };
  const run = async (write: () => Promise<Outcome>) => {
    setOutcome(null);
    try {
      const result = await write();
      setOutcome(result);
      if (result === 'ok') setVersion((v) => v + 1);
    } catch {
      setOutcome('failed');
    }
  };
  const save = () =>
    run(() =>
      saveGateTemplateOf({
        clientId: clientId === BASE ? null : clientId,
        countryCode: country.trim() === '' ? null : country.trim().toUpperCase(),
        name: name.trim(),
        gates: gates.map((g) => ({
          key: g.key.trim(),
          name: g.name.trim(),
          ...(g.readinessDays.trim() === '' ? {} : { readinessDays: Number(g.readinessDays) }),
        })),
      }),
    );

  return (
    <>
      <PageHeader eyebrow={`/ ${t('admin.title')}`} title={t('admin.title')} />
      <Card>
        <h2>{t('admin.gates.title')}</h2>
        <p>{t('admin.gates.intro')}</p>
        {templates === null ? <p>{t('common.loading')}</p> : null}
        {templates === 'forbidden' ? <p>{t('admin.gates.noAccess')}</p> : null}
        {templates === 'failed' ? <FormMessage tone="error">{t('admin.gates.failed')}</FormMessage> : null}
        {Array.isArray(templates) ? (
          <>
            {templates.length === 0 ? (
              <p>{t('admin.gates.none')}</p>
            ) : (
              <table className="ocs-table">
                <thead>
                  <tr>
                    <th scope="col">{t('admin.gates.col.scope')}</th>
                    <th scope="col">{t('admin.gates.col.name')}</th>
                    <th scope="col">{t('admin.gates.col.gates')}</th>
                    <th scope="col">{t('admin.gates.col.do')}</th>
                  </tr>
                </thead>
                <tbody>
                  {templates.map((tpl) => (
                    <tr key={tpl.id}>
                      <td>{scopeOf(tpl)}</td>
                      <td>{tpl.name}</td>
                      <td>{tpl.gates.map((g) => g.name).join(' → ')}</td>
                      <td>
                        <Button
                          type="button"
                          aria-label={`${t('admin.gates.edit')}: ${tpl.name}`}
                          onClick={() => {
                            edit(tpl);
                          }}
                        >
                          {t('admin.gates.edit')}
                        </Button>{' '}
                        <Button
                          type="button"
                          aria-label={`${t('admin.gates.archive')}: ${tpl.name}`}
                          onClick={() => void run(() => archiveGateTemplateOf(tpl.id))}
                        >
                          {t('admin.gates.archive')}
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            <h3>{t('admin.gates.editor')}</h3>
            <Form onSubmit={save}>
              <SelectField
                id="gate-scope-client"
                label={t('admin.gates.client')}
                value={clientId}
                options={[
                  { value: BASE, label: t('admin.gates.base') },
                  ...clients.map((c) => ({ value: c.id, label: `${c.shortCode} — ${c.name}` })),
                ]}
                onChange={(e) => {
                  setClientId(e.currentTarget.value);
                }}
              />
              <TextField
                id="gate-scope-country"
                label={t('admin.gates.country')}
                hint={t('admin.gates.countryHint')}
                maxLength={2}
                value={country}
                onChange={(e) => {
                  setCountry(e.currentTarget.value);
                }}
              />
              <TextField
                id="gate-template-name"
                label={t('admin.gates.name')}
                value={name}
                onChange={(e) => {
                  setName(e.currentTarget.value);
                }}
              />
              <ol className="ocs-stack">
                {gates.map((g, n) => (
                  // Rows have no stable id while being typed; the index is the row's identity here.
                  <li key={n}>
                    <TextField
                      id={`gate-${String(n)}-name`}
                      label={`${t('admin.gates.gateName')} ${String(n + 1)}`}
                      value={g.name}
                      onChange={(e) => {
                        const value = e.currentTarget.value;
                        setGate(
                          n,
                          g.key === keyOf(g.name) ? { name: value, key: keyOf(value) } : { name: value },
                        );
                      }}
                    />
                    <TextField
                      id={`gate-${String(n)}-key`}
                      label={`${t('admin.gates.gateKey')} ${String(n + 1)}`}
                      hint={t('admin.gates.keyHint')}
                      value={g.key}
                      onChange={(e) => {
                        setGate(n, { key: e.currentTarget.value });
                      }}
                    />
                    <TextField
                      id={`gate-${String(n)}-days`}
                      label={`${t('admin.gates.readinessDays')} ${String(n + 1)}`}
                      type="number"
                      min={0}
                      max={60}
                      value={g.readinessDays}
                      onChange={(e) => {
                        setGate(n, { readinessDays: e.currentTarget.value });
                      }}
                    />
                    <Button
                      type="button"
                      aria-label={`${t('admin.gates.up')} ${String(n + 1)}`}
                      disabled={n === 0}
                      onClick={() => {
                        move(n, -1);
                      }}
                    >
                      ↑
                    </Button>{' '}
                    <Button
                      type="button"
                      aria-label={`${t('admin.gates.down')} ${String(n + 1)}`}
                      disabled={n === gates.length - 1}
                      onClick={() => {
                        move(n, 1);
                      }}
                    >
                      ↓
                    </Button>{' '}
                    <Button
                      type="button"
                      aria-label={`${t('admin.gates.remove')} ${String(n + 1)}`}
                      disabled={gates.length === 1}
                      onClick={() => {
                        setGates((gs) => gs.filter((_, i) => i !== n));
                      }}
                    >
                      {t('admin.gates.remove')}
                    </Button>
                  </li>
                ))}
              </ol>
              <div>
                <Button
                  type="button"
                  onClick={() => {
                    setGates((gs) => [...gs, emptyGate()]);
                  }}
                >
                  {t('admin.gates.add')}
                </Button>{' '}
                <Button type="submit">{t('admin.gates.save')}</Button>
              </div>
              {outcome ? (
                <FormMessage tone={outcome === 'ok' ? 'ok' : 'error'}>
                  {t(`admin.gates.outcome.${outcome}`)}
                </FormMessage>
              ) : null}
            </Form>
          </>
        ) : null}
      </Card>
      <AgentResourceSetup />
    </>
  );
}
